**What this code covers**

- CDN simulator with edge servers, caching, and origin fallback
- CDN with multiple edge locations and cache management
- Handle CDN request
- Invalidate cache across edges
- Cache MISS — fetch from origin
- Simplified — in reality uses latency-based routing
- Evict LRU if needed
- First request — cache MISS

**Defines:** `CacheEntry`, `EdgeServer`, `CDN`, `UploadPolicy`, `ObjectStorage`, `ImageTransform`, `ImageCDN`, `CacheConfig`, `MultiTierCache`, `fetch_from_db()`

### Example 1: CDN Simulator

```python
"""
CDN simulator with edge servers, caching, and origin fallback
"""
from dataclasses import dataclass, field
from typing import Dict, Optional
import time
import hashlib

@dataclass
class CacheEntry:
    content: bytes
    content_type: str
    etag: str
    created_at: float
    ttl: int  # seconds
    size: int
    hit_count: int = 0

    @property
    def is_expired(self):
        return time.time() > self.created_at + self.ttl

@dataclass
class EdgeServer:
    location: str
    cache: Dict[str, CacheEntry] = field(default_factory=dict)
    max_cache_size: int = 100_000_000  # 100MB
    current_size: int = 0
    stats: dict = field(default_factory=lambda: {"hits": 0, "misses": 0})

class CDN:
    """CDN with multiple edge locations and cache management"""

    def __init__(self):
        self.edges: Dict[str, EdgeServer] = {}
        self.origin_content: Dict[str, dict] = {}  # Simulated origin
        self.global_stats = {"total_requests": 0, "cache_hits": 0}

    def add_edge(self, location: str, max_cache_mb: int = 100):
        self.edges[location] = EdgeServer(location=location,
                                           max_cache_size=max_cache_mb * 1_000_000)

    def set_origin_content(self, path: str, content: bytes, content_type: str, ttl: int = 3600):
        self.origin_content[path] = {
            "content": content, "content_type": content_type,
            "etag": hashlib.md5(content).hexdigest(), "ttl": ttl
        }

    def request(self, path: str, user_location: str, if_none_match: str = None) -> dict:
        """Handle CDN request"""
        self.global_stats["total_requests"] += 1
        edge = self._get_nearest_edge(user_location)

        # Check cache
        cached = edge.cache.get(path)
        if cached and not cached.is_expired:
            # Conditional request (ETag)
            if if_none_match == cached.etag:
                return {"status": 304, "body": None, "cache": "HIT",
                        "edge": edge.location, "latency_ms": 2}

            cached.hit_count += 1
            edge.stats["hits"] += 1
            self.global_stats["cache_hits"] += 1
            return {
                "status": 200,
                "body": cached.content,
                "content_type": cached.content_type,
                "etag": cached.etag,
                "cache": "HIT",
                "edge": edge.location,
                "latency_ms": 5  # Fast edge response
            }

        # Cache MISS — fetch from origin
        edge.stats["misses"] += 1
        origin_data = self.origin_content.get(path)
        if not origin_data:
            return {"status": 404, "body": None, "cache": "MISS"}

        # Cache at edge
        entry = CacheEntry(
            content=origin_data["content"],
            content_type=origin_data["content_type"],
            etag=origin_data["etag"],
            created_at=time.time(),
            ttl=origin_data["ttl"],
            size=len(origin_data["content"])
        )
        self._cache_at_edge(edge, path, entry)

        return {
            "status": 200,
            "body": origin_data["content"],
            "content_type": origin_data["content_type"],
            "etag": origin_data["etag"],
            "cache": "MISS",
            "edge": edge.location,
            "latency_ms": 150  # Slow origin fetch
        }

    def purge(self, path: str, locations: list = None):
        """Invalidate cache across edges"""
        targets = locations or self.edges.keys()
        for loc in targets:
            edge = self.edges.get(loc)
            if edge and path in edge.cache:
                entry = edge.cache.pop(path)
                edge.current_size -= entry.size

    def _get_nearest_edge(self, user_location: str) -> EdgeServer:
        # Simplified — in reality uses latency-based routing
        return self.edges.get(user_location, list(self.edges.values())[0])

    def _cache_at_edge(self, edge: EdgeServer, path: str, entry: CacheEntry):
        # Evict LRU if needed
        while edge.current_size + entry.size > edge.max_cache_size:
            self._evict_lru(edge)
        edge.cache[path] = entry
        edge.current_size += entry.size

    def _evict_lru(self, edge: EdgeServer):
        if not edge.cache:
            return
        oldest_key = min(edge.cache, key=lambda k: edge.cache[k].created_at)
        entry = edge.cache.pop(oldest_key)
        edge.current_size -= entry.size

    def get_stats(self) -> dict:
        hit_ratio = (self.global_stats["cache_hits"] /
                     max(1, self.global_stats["total_requests"])) * 100
        return {
            **self.global_stats,
            "hit_ratio": f"{hit_ratio:.1f}%",
            "edge_stats": {loc: e.stats for loc, e in self.edges.items()}
        }

# Usage
cdn = CDN()
cdn.add_edge("us-east")
cdn.add_edge("eu-west")
cdn.add_edge("ap-southeast")

cdn.set_origin_content("/images/logo.png", b"PNG_DATA_HERE", "image/png", ttl=86400)
cdn.set_origin_content("/css/styles.css", b"body { color: red }", "text/css", ttl=3600)

# First request — cache MISS
r1 = cdn.request("/images/logo.png", "us-east")
print(f"Request 1: {r1['cache']} from {r1['edge']} ({r1['latency_ms']}ms)")

# Second request — cache HIT
r2 = cdn.request("/images/logo.png", "us-east")
print(f"Request 2: {r2['cache']} from {r2['edge']} ({r2['latency_ms']}ms)")

print(f"Stats: {cdn.get_stats()}")
```

### Example 2: Pre-signed URL for Direct Upload

```python
"""
Generate pre-signed URLs for direct client-to-storage upload
(like S3 pre-signed URLs)
"""
import hmac
import hashlib
import time
import uuid
from dataclasses import dataclass
from typing import Optional

@dataclass
class UploadPolicy:
    max_size_bytes: int
    allowed_types: list
    expires_in: int  # seconds

class ObjectStorage:
    """Simulated object storage with pre-signed URLs"""

    def __init__(self, secret_key: str):
        self.secret_key = secret_key
        self.objects: dict = {}
        self.presigned_policies: dict = {}

    def generate_presigned_upload(self, key: str, policy: UploadPolicy) -> dict:
        """Generate pre-signed URL for direct upload"""
        expires_at = int(time.time()) + policy.expires_in
        token = str(uuid.uuid4())

        # Create signature
        string_to_sign = f"PUT:{key}:{expires_at}:{token}"
        signature = hmac.new(
            self.secret_key.encode(),
            string_to_sign.encode(),
            hashlib.sha256
        ).hexdigest()

        self.presigned_policies[token] = {
            "key": key,
            "expires_at": expires_at,
            "max_size": policy.max_size_bytes,
            "allowed_types": policy.allowed_types,
            "signature": signature,
            "used": False
        }

        return {
            "upload_url": f"https://storage.example.com/{key}",
            "method": "PUT",
            "headers": {
                "X-Upload-Token": token,
                "X-Upload-Signature": signature,
                "X-Upload-Expires": str(expires_at),
            },
            "constraints": {
                "max_size_bytes": policy.max_size_bytes,
                "allowed_types": policy.allowed_types,
                "expires_at": expires_at
            }
        }

    def validate_upload(self, token: str, content_type: str, size: int, data: bytes) -> dict:
        """Validate and accept upload using pre-signed URL"""
        policy = self.presigned_policies.get(token)
        if not policy:
            return {"error": "Invalid token", "status": 403}
        if policy["used"]:
            return {"error": "Token already used", "status": 403}
        if time.time() > policy["expires_at"]:
            return {"error": "Upload URL expired", "status": 410}
        if size > policy["max_size"]:
            return {"error": f"File too large: {size} > {policy['max_size']}", "status": 413}
        if content_type not in policy["allowed_types"]:
            return {"error": f"Type {content_type} not allowed", "status": 415}

        # Store
        policy["used"] = True
        key = policy["key"]
        self.objects[key] = {
            "data": data, "content_type": content_type,
            "size": size, "created_at": time.time(),
            "etag": hashlib.md5(data).hexdigest()
        }

        return {
            "status": 200,
            "key": key,
            "etag": self.objects[key]["etag"],
            "url": f"https://cdn.example.com/{key}"
        }

    def generate_presigned_download(self, key: str, expires_in: int = 3600) -> str:
        """Generate pre-signed URL for time-limited download"""
        expires_at = int(time.time()) + expires_in
        signature = hmac.new(
            self.secret_key.encode(),
            f"GET:{key}:{expires_at}".encode(),
            hashlib.sha256
        ).hexdigest()
        return f"https://cdn.example.com/{key}?expires={expires_at}&sig={signature}"

# Usage
storage = ObjectStorage(secret_key="my-secret-key-123")

# Generate upload URL
upload_info = storage.generate_presigned_upload(
    key="uploads/user-123/profile.jpg",
    policy=UploadPolicy(max_size_bytes=5_000_000, allowed_types=["image/jpeg", "image/png"], expires_in=300)
)
print(f"Upload URL: {upload_info['upload_url']}")

# Client uploads directly (simulated)
result = storage.validate_upload(
    token=upload_info["headers"]["X-Upload-Token"],
    content_type="image/jpeg",
    size=150_000,
    data=b"JPEG_DATA_HERE"
)
print(f"Upload result: {result}")

# Generate download URL
download_url = storage.generate_presigned_download("uploads/user-123/profile.jpg")
print(f"Download URL: {download_url}")
```

### Example 3: Image Processing Pipeline

```python
"""
On-the-fly image transformation at CDN edge
(like Cloudinary/Imgix pattern)
"""
from dataclasses import dataclass
from typing import Optional, Tuple
import hashlib

@dataclass
class ImageTransform:
    width: Optional[int] = None
    height: Optional[int] = None
    quality: int = 85
    format: str = "webp"
    fit: str = "cover"  # cover, contain, fill

    def cache_key(self) -> str:
        params = f"w{self.width}_h{self.height}_q{self.quality}_f{self.format}_{self.fit}"
        return hashlib.md5(params.encode()).hexdigest()[:12]

class ImageCDN:
    """CDN with on-the-fly image transformation"""

    def __init__(self):
        self.originals: dict = {}
        self.transform_cache: dict = {}

    def store_original(self, path: str, data: bytes, content_type: str):
        self.originals[path] = {"data": data, "type": content_type}

    def get_image(self, path: str, transform: ImageTransform = None) -> dict:
        """Request image with optional transformation"""
        original = self.originals.get(path)
        if not original:
            return {"status": 404, "error": "Image not found"}

        if not transform:
            return {"status": 200, "data": original["data"],
                    "content_type": original["type"], "cache": "ORIGINAL"}

        # Check transform cache
        cache_key = f"{path}:{transform.cache_key()}"
        if cache_key in self.transform_cache:
            cached = self.transform_cache[cache_key]
            return {"status": 200, "data": cached["data"],
                    "content_type": f"image/{transform.format}", "cache": "HIT"}

        # Transform (simulated — would use Pillow in production)
        transformed = self._apply_transform(original["data"], transform)
        self.transform_cache[cache_key] = {"data": transformed}

        return {
            "status": 200, "data": transformed,
            "content_type": f"image/{transform.format}",
            "cache": "MISS",
            "headers": {
                "Cache-Control": "public, max-age=31536000",
                "Vary": "Accept"
            }
        }

    def _apply_transform(self, data: bytes, transform: ImageTransform) -> bytes:
        """Simulate image transformation"""
        # In production: use Pillow, libvips, or sharp
        desc = f"Transformed: {transform.width}x{transform.height} q={transform.quality} {transform.format}"
        return desc.encode()

    def build_url(self, path: str, transform: ImageTransform) -> str:
        """Build transformation URL"""
        params = []
        if transform.width: params.append(f"w={transform.width}")
        if transform.height: params.append(f"h={transform.height}")
        params.append(f"q={transform.quality}")
        params.append(f"fmt={transform.format}")
        params.append(f"fit={transform.fit}")
        return f"https://img-cdn.example.com/{path}?{'&'.join(params)}"

# Usage
cdn = ImageCDN()
cdn.store_original("/photos/landscape.jpg", b"LARGE_JPEG_DATA", "image/jpeg")

# Thumbnail for mobile
thumb = cdn.get_image("/photos/landscape.jpg", ImageTransform(width=300, height=200, quality=75))
print(f"Thumbnail: {thumb['cache']} - {thumb['data']}")

# High-res for desktop
hires = cdn.get_image("/photos/landscape.jpg", ImageTransform(width=1920, height=1080, quality=90))
print(f"High-res: {hires['cache']} - {hires['data']}")

# URL building
url = cdn.build_url("/photos/landscape.jpg", ImageTransform(width=400, height=300, format="webp"))
print(f"CDN URL: {url}")
```

### Example 4: Multi-tier Caching System

```python
"""
L1 (in-memory) → L2 (Redis) → L3 (CDN) → Origin
"""
import time
from collections import OrderedDict
from dataclasses import dataclass

@dataclass
class CacheConfig:
    l1_max_items: int = 1000    # Local memory
    l1_ttl: int = 60            # 1 minute
    l2_ttl: int = 300           # 5 minutes
    l3_ttl: int = 3600          # 1 hour

class MultiTierCache:
    def __init__(self, config: CacheConfig = None):
        self.config = config or CacheConfig()
        self.l1_cache = OrderedDict()  # LRU local cache
        self.l2_cache = {}              # Simulated Redis
        self.l3_cache = {}              # Simulated CDN
        self.stats = {"l1_hits": 0, "l2_hits": 0, "l3_hits": 0, "origin_fetches": 0}

    def get(self, key: str, fetch_fn=None):
        """Check each cache tier, fallback to origin"""

        # L1: Local memory (fastest, smallest)
        result = self._l1_get(key)
        if result is not None:
            self.stats["l1_hits"] += 1
            return {"data": result, "tier": "L1_MEMORY", "latency_ms": 0.1}

        # L2: Redis (fast, shared across instances)
        result = self._l2_get(key)
        if result is not None:
            self.stats["l2_hits"] += 1
            self._l1_set(key, result)  # Promote to L1
            return {"data": result, "tier": "L2_REDIS", "latency_ms": 1}

        # L3: CDN edge (fast for static, global)
        result = self._l3_get(key)
        if result is not None:
            self.stats["l3_hits"] += 1
            self._l2_set(key, result)
            self._l1_set(key, result)
            return {"data": result, "tier": "L3_CDN", "latency_ms": 5}

        # Origin: Database/API (slowest)
        if fetch_fn:
            self.stats["origin_fetches"] += 1
            result = fetch_fn(key)
            self._l3_set(key, result)
            self._l2_set(key, result)
            self._l1_set(key, result)
            return {"data": result, "tier": "ORIGIN", "latency_ms": 50}

        return None

    def invalidate(self, key: str):
        """Invalidate across all tiers"""
        self.l1_cache.pop(key, None)
        self.l2_cache.pop(key, None)
        self.l3_cache.pop(key, None)

    def _l1_get(self, key):
        entry = self.l1_cache.get(key)
        if entry and time.time() < entry["expires"]:
            self.l1_cache.move_to_end(key)
            return entry["data"]
        return None

    def _l1_set(self, key, data):
        if len(self.l1_cache) >= self.config.l1_max_items:
            self.l1_cache.popitem(last=False)  # Remove LRU
        self.l1_cache[key] = {"data": data, "expires": time.time() + self.config.l1_ttl}

    def _l2_get(self, key):
        entry = self.l2_cache.get(key)
        if entry and time.time() < entry["expires"]:
            return entry["data"]
        return None

    def _l2_set(self, key, data):
        self.l2_cache[key] = {"data": data, "expires": time.time() + self.config.l2_ttl}

    def _l3_get(self, key):
        entry = self.l3_cache.get(key)
        if entry and time.time() < entry["expires"]:
            return entry["data"]
        return None

    def _l3_set(self, key, data):
        self.l3_cache[key] = {"data": data, "expires": time.time() + self.config.l3_ttl}

    def get_stats(self):
        total = sum(self.stats.values())
        return {**self.stats, "total": total,
                "hit_ratio": f"{(total - self.stats['origin_fetches']) / max(total, 1) * 100:.1f}%"}

# Usage
cache = MultiTierCache()

def fetch_from_db(key):
    return {"user_id": key, "name": "Alice", "source": "database"}

# First call — origin
r1 = cache.get("user:123", fetch_from_db)
print(f"1st: {r1['tier']} ({r1['latency_ms']}ms)")

# Second call — L1 memory
r2 = cache.get("user:123")
print(f"2nd: {r2['tier']} ({r2['latency_ms']}ms)")

print(f"Stats: {cache.get_stats()}")
```

### Example 5: Static Site Deployment Pipeline

```python
"""
Deploy static site to CDN with cache busting and atomic deploys
"""
import hashlib
import time
from dataclasses import dataclass, field
from typing import Dict, List

@dataclass
class Asset:
    path: str
    content: bytes
    content_type: str
    hashed_path: str = ""  # path with content hash for cache busting

class StaticSiteDeployer:
    """Deploy static sites to CDN with version management"""

    def __init__(self):
        self.deployments: Dict[str, dict] = {}
        self.active_version: str = ""
        self.cdn_cache: Dict[str, dict] = {}

    def deploy(self, version: str, assets: List[Asset]) -> dict:
        """Deploy new version with content-hashed URLs"""
        deployment = {"version": version, "assets": {}, "created_at": time.time()}

        for asset in assets:
            # Content-hash the filename for cache busting
            content_hash = hashlib.md5(asset.content).hexdigest()[:8]
            ext = asset.path.rsplit(".", 1)[-1]
            base = asset.path.rsplit(".", 1)[0]
            asset.hashed_path = f"{base}.{content_hash}.{ext}"

            deployment["assets"][asset.path] = {
                "hashed_path": asset.hashed_path,
                "content": asset.content,
                "content_type": asset.content_type,
                "size": len(asset.content),
                "cache_control": "public, max-age=31536000, immutable"
            }

            # Upload to CDN (hashed path = forever cacheable)
            self.cdn_cache[asset.hashed_path] = {
                "content": asset.content,
                "content_type": asset.content_type,
                "cache_control": "public, max-age=31536000, immutable"
            }

        # Generate index.html with hashed references
        manifest = {
            original: info["hashed_path"]
            for original, info in deployment["assets"].items()
        }
        deployment["manifest"] = manifest

        self.deployments[version] = deployment

        # Atomic switch: update index.html to point to new hashed assets
        self.active_version = version

        return {
            "version": version,
            "assets_deployed": len(assets),
            "manifest": manifest,
            "status": "deployed"
        }

    def rollback(self, version: str) -> dict:
        """Instantly rollback to previous version (just switch pointer)"""
        if version not in self.deployments:
            raise ValueError(f"Version {version} not found")
        self.active_version = version
        return {"status": "rolled_back", "active_version": version}

    def get_asset(self, path: str) -> dict:
        """Get asset from current active deployment"""
        deployment = self.deployments.get(self.active_version)
        if not deployment:
            return {"status": 404}

        asset_info = deployment["assets"].get(path)
        if not asset_info:
            return {"status": 404}

        return {
            "status": 200,
            "redirect_to": asset_info["hashed_path"],
            "cache_control": asset_info["cache_control"]
        }

# Deploy v1
deployer = StaticSiteDeployer()
v1 = deployer.deploy("v1.0", [
    Asset("/css/styles.css", b"body { color: blue }", "text/css"),
    Asset("/js/app.js", b"console.log('v1')", "application/javascript"),
])
print(f"V1 deployed: {v1['manifest']}")

# Deploy v2 (only CSS changed — JS reuses cached version)
v2 = deployer.deploy("v2.0", [
    Asset("/css/styles.css", b"body { color: red }", "text/css"),
    Asset("/js/app.js", b"console.log('v1')", "application/javascript"),  # Same content
])
print(f"V2 deployed: {v2['manifest']}")

# Rollback to v1 — instant, no re-upload needed
rollback = deployer.rollback("v1.0")
print(f"Rollback: {rollback}")
```
